def count_fair_sum_pairs(nums,lower,upper):
    import bisect
    nums=sorted(nums);answer=0
    for index,value in enumerate(nums):
        start=bisect.bisect_left(nums,lower-value,index+1)
        end=bisect.bisect_right(nums,upper-value,index+1)
        answer+=end-start
    return answer

